<?php require_once __DIR__.'/../conexion.php'; if(!$bd_disponible){header('Location: ../index.html');exit;} ?>
<?php require_once __DIR__.'/../seguridad.php';exigir_sesion();require_once __DIR__.'/../conexion.php';
$admin=es_admin()?1:0;$profesor=profesor_actual();$id=alumno_actual();$st=$conexion->prepare("SELECT a.matricula_al AS Matricula,CONCAT(a.nombre_al,' ',a.apaterno_al) AS Alumno,m.descripcion_mat AS Materia,CONCAT(p.nombre_prof,' ',p.apaterno_prof) AS Profesor FROM asignar_materia am JOIN alumnos a ON a.idalumn=am.idalumn JOIN materias m ON m.idmateria=am.idmateria JOIN profesores p ON p.idprof=am.idprof WHERE (?=1 OR am.idprof=? OR a.idalumn=?) ORDER BY Alumno,Materia");$st->bind_param('iii',$admin,$profesor,$id);$st->execute();$r=$st->get_result();$fields=$r->fetch_fields();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Materias por alumno</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/estilos.css" rel="stylesheet"></head><body><nav class="navbar navbar-dark barra"><div class="container"><a class="navbar-brand" href="../index.php">Sistema Escolar</a></div></nav><main class="container py-4"><a class="btn btn-secondary mb-3 d-print-none" href="../index.php">Volver</a><h2>Materias por alumno</h2><div class="card"><div class="card-body table-responsive"><table class="table table-striped table-bordered"><thead class="table-dark"><tr><?php foreach($fields as $f):?><th><?=htmlspecialchars($f->name)?></th><?php endforeach;?></tr></thead><tbody><?php while($row=$r->fetch_assoc()):?><tr><?php foreach($row as $v):?><td><?=htmlspecialchars($v===null?'Sin capturar':(string)$v)?></td><?php endforeach;?></tr><?php endwhile;?></tbody></table></div></div><button onclick="print()" class="btn btn-primary mt-3 d-print-none">Imprimir</button></main></body></html>